Item.method_code:
const itm = document.item;
if (!itm) {
	return;
}

const isStandardMessage = aras.getItemProperty(itm, 'is_standard_template') == '1' ? true : false;
if (isStandardMessage) {
	const customHtmlElem = getFieldByName('custom_html');
	if (customHtmlElem) {
		customHtmlElem.style.visibility = 'hidden';
	}

	const widthElem = getFieldByName('width');
	const heightElem = getFieldByName('height');

	if (widthElem) {
		widthElem.style.display = 'none';
	}

	if (heightElem) {
		heightElem.style.display = 'none';
	}
} else {
	const cssElem = getFieldByName('css');
	if (cssElem) {
		cssElem.style.display = 'none';
	}
}
